#[unsafe(no_mangle)]
pub extern "C" fn init(width: u32, height: u32) {
    *SIZE.lock().unwrap() = (width as usize, height as usize);
    PIXELS.lock().unwrap().resize((width * height * 4) as usize, 255);
}

