#[unsafe(no_mangle)]
pub extern "C" fn frame(t_ms: u32) -> *const u8 {
    let (width, height) = *SIZE.lock().unwrap();
    let mut pixels = PIXELS.lock().unwrap();
    for y in 0..height {
        for x in 0..width {
            let i = (y * width + x) * 4;
            let wave = (x as f64 / 12.0 + y as f64 / 9.0 + t_ms as f64 / 400.0).sin();
